using System;
using System.IO;
using UnityEngine;
using UnityEngine.UIElements;

namespace Azarashi.UnityView.Editor
{
    /// <summary>Compare the native port against samples generated by the original TypeScript presentation.</summary>
    public static class PresentationValidation
    {
        [Serializable]
        private sealed class Fixture
        {
            public MotionCase[] cases; public GuideCase[] guides; public CameraOrbit[] cameraOrbits; public ChoiceCase[] choices;
        }
        [Serializable] private sealed class ChoiceCase
        {
            public PieceState selected; public string owner; public Preview[] options; public int[] offered; public bool warning;
        }
        [Serializable]
        private sealed class CameraOrbit
        {
            public Vector3 from, to; public CameraSample[] samples;
        }
        [Serializable]
        private sealed class CameraSample
        {
            public float t; public Vector3 position;
        }
        [Serializable]
        private sealed class MotionCase
        {
            public Position before; public Preview preview; public string stage; public float duration, playbackDuration; public Sample[] samples; public Capture[] captures; public Flight[] flights; public NativeAudioCue[] audio, resolveAudio;
        }
        [Serializable]
        private sealed class Sample
        {
            public float t, yaw, scale, change, pitch, roll, thrust; public bool promoted; public float[] position, stretch;
        }
        [Serializable]
        private sealed class Capture
        {
            public string id; public float at;
        }
        [Serializable]
        private sealed class Flight
        {
            public string id; public float launch, arrival;
        }
        [Serializable]
        private sealed class GuideCase
        {
            public int bits; public string fill, dot, outline; public float fillOpacity, dotOpacity, outlineOpacity;
        }
        private static void Close(float actual, float expected, string name)
        {
            if (Mathf.Abs(actual - expected) > .00015f)
                throw new Exception("Presentation parity: " + name + " expected=" + expected + " actual=" + actual);
        }
        public static void Run(NativeGameData data)
        {
            ValidateRetainedScroll();
            ValidateRetainedOrder();
            UirStagingPatch.ValidateBounds();
            ValidateShadowProjection(data.Assets.lighting, Vector3.zero);
            ValidateShadowProjection(data.Assets.catalogLighting, new Vector3(50, 0, 0));
            // Exported material colors are already linear. ShaderLab Color properties
            // convert from sRGB on upload, even when their values are set with SetVector.
            foreach (var name in new[] { "Azarashi/Surface", "Azarashi/Ocean", "Azarashi/Unlit" })
            {
                var shader = Shader.Find(name);
                foreach (var property in new[] { "_Color", "_Emission" })
                {
                    var index = shader.FindPropertyIndex(property);
                    if (index >= 0 && shader.GetPropertyType(index) != UnityEngine.Rendering.ShaderPropertyType.Vector)
                        throw new Exception(name + " " + property + " must preserve exported linear values.");
                }
            }
            var fixture = JsonUtility.FromJson<Fixture>(File.ReadAllText(Path.GetFullPath("../.openai/unity-presentation-fixtures.json")));
            var ownKingWarnings = 0;
            foreach (var item in fixture.choices)
            {
                var offered = NativeChoices.Offered(item.selected, item.options);
                if (offered.Length != item.offered.Length || NativeChoices.RequiresChoice(offered, item.owner) != item.warning)
                    throw new Exception("Capture choice differs from the source UI.");
                for (var i = 0; i < offered.Length; i++)
                    if (offered[i] != item.options[item.offered[i]])
                        throw new Exception("Offered capture action differs from the source UI.");
                if (offered.Length == 1 && item.warning)
                    ownKingWarnings++;
            }
            if (ownKingWarnings == 0)
                throw new Exception("Capture choice fixtures did not cover the own-king confirmation.");
            Debug.Log("Capture choice parity passed: " + fixture.choices.Length + " destinations, including " + ownKingWarnings + " own-king confirmations.");
            var count = 0;
            foreach (var item in fixture.cases)
            {
                if (string.IsNullOrEmpty(item.preview.action.transformation?.type))
                    item.preview.action.transformation = null;
                var motion = new NativeMotion(data, item.before, item.preview, item.stage == "choice");
                Close(motion.Duration, item.duration, "duration");
                ValidateAudio(motion, item.audio);
                if (item.stage != "choice")
                    Close(motion.PlaybackDuration, item.playbackDuration, "playback");
                foreach (var sample in item.samples)
                {
                    var pose = motion.Sample(sample.t);
                    var body = motion.Dynamics(sample.t);
                    for (var i = 0; i < 3; i++)
                    {
                        Close(pose.position[i], sample.position[i], "position " + i);
                        Close(body.stretch[i], sample.stretch[i], "stretch " + i);
                    }
                    Close(pose.yaw, sample.yaw, "yaw");
                    Close(pose.scale, sample.scale, "scale");
                    Close(body.pitch, sample.pitch, "pitch");
                    Close(body.roll, sample.roll, "roll");
                    Close(body.thrust, sample.thrust, "thrust");
                    Close(motion.Change(sample.t), sample.change, "change");
                    if (pose.promoted != sample.promoted)
                        throw new Exception("Presentation parity: form switch");
                    count++;
                }
                if (item.stage != "choice")
                    foreach (var flight in item.flights)
                    {
                        var victim = Array.Find(item.preview.captured, p => p.id == flight.id);
                        var index = Array.FindIndex(item.flights, f => f.id == flight.id);
                        Close(motion.TransferLaunch(victim, index) - motion.Started, flight.launch, "orb launch");
                        Close(motion.TransferArrival(victim, index) - motion.Started, flight.arrival, "orb arrival");
                    }
                motion.Resolve(item.preview);
                ValidateAudio(motion, item.resolveAudio);
                motion.Return();
                if (NativeAudio.Cues(motion).Length != 0) throw new Exception("Returning choices must not play audio.");
            }
            foreach (var item in fixture.guides)
            {
                var b = item.bits;
                var s = new GuideState { stationary = (b & 1) != 0, stationaryAnchor = (b & 2) != 0, inspectingEnemy = (b & 4) != 0, active = (b & 8) != 0, additional = (b & 16) != 0, reachable = (b & 32) != 0, last = (b & 64) != 0, legal = (b & 128) != 0, unsafeCell = (b & 256) != 0, previewUnsafe = (b & 512) != 0, kingDanger = (b & 1024) != 0, previewKingDanger = (b & 2048) != 0, transformationSafe = (b & 4096) != 0, kingCaptureTrap = (b & 8192) != 0, previewKingCaptureTrap = (b & 16384) != 0 };
                var actual = NativeGuides.Style(s, data.Config.colors);
                if (actual.fill != item.fill || actual.dot != item.dot || actual.outline != item.outline)
                    throw new Exception("Presentation parity: guide palette at " + b);
                Close(actual.fillOpacity, item.fillOpacity, "fill alpha");
                Close(actual.dotOpacity, item.dotOpacity, "dot alpha");
                Close(actual.outlineOpacity, item.outlineOpacity, "outline alpha");
            }
            var cameraCount = 0;
            foreach (var item in fixture.cameraOrbits)
                foreach (var sample in item.samples)
                {
                    var actual = NativeCamera.SampleOrbit(new Vector3(item.from.x, item.from.y, -item.from.z), new Vector3(item.to.x, item.to.y, -item.to.z), sample.t);
                    Close(actual.x, sample.position.x, "camera x");
                    Close(actual.y, sample.position.y, "camera y");
                    Close(actual.z, -sample.position.z, "camera z");
                    cameraCount++;
                }
            var host = new GameObject("Camera startup validation");
            try
            {
                var camera = host.AddComponent<Camera>();
                var native = new NativeCamera(camera);
                native.Frame(Rect.zero, "south", false, null, data, false);
                native.Tick(false);
                native.Frame(new Rect(8, 144, 1264, 502), "south", false, null, data, false);
                native.Tick(false);
                var p = camera.transform.position;
                if (float.IsNaN(p.x) || float.IsNaN(p.y) || float.IsNaN(p.z) || float.IsInfinity(p.sqrMagnitude))
                    throw new Exception("Camera startup before HUD layout produced a non-finite position.");
                for (var i = 0; i < 16; i++)
                    if (float.IsNaN(camera.projectionMatrix[i]) || float.IsInfinity(camera.projectionMatrix[i]))
                        throw new Exception("Camera startup produced a non-finite projection.");
            }
            finally { UnityEngine.Object.DestroyImmediate(host); }
            Debug.Log("Presentation parity passed: " + count + " motion samples, " + fixture.guides.Length + " guide states, " + cameraCount + " camera samples and camera startup against original TypeScript.");
        }
        private static void ValidateAudio(NativeMotion motion, NativeAudioCue[] expected)
        {
            var actual = NativeAudio.Cues(motion);
            if (actual.Length != expected.Length) throw new Exception("Motion audio cue count differs from the source.");
            for (var i = 0; i < actual.Length; i++)
            {
                if (actual[i].clip != expected[i].clip) throw new Exception("Motion audio clip differs from the source.");
                Close(actual[i].at, expected[i].at, "audio " + actual[i].clip);
            }
        }
        private static void ValidateShadowProjection(LightingSettings lighting, Vector3 offset)
        {
            var mirror = Matrix4x4.Scale(new Vector3(1, 1, -1));
            foreach (var light in lighting.directional)
            {
                if (!light.shadows) continue;
                var s = light.shadow;
                var matrix = SceneRenderer.Matrix(s.matrix) * mirror * Matrix4x4.Translate(-offset);
                foreach (var sample in s.samples)
                {
                    var p = new Vector3(sample.point[0], sample.point[1], -sample.point[2]) + offset;
                    var n = new Vector3(sample.normal[0], sample.normal[1], -sample.normal[2]).normalized;
                    var uv = matrix.MultiplyPoint(p + n * s.normalBias);
                    Close(uv.x, sample.uv[0], "shadow u");
                    Close(uv.y, sample.uv[1], "shadow v");
                    Close(uv.z + s.bias, sample.uv[2], "shadow depth");
                }
                Debug.Log("Source shadow projection parity passed: " + s.samples.Length + " receiver samples, map=" + s.mapSize[0]);
            }
        }
        private static void ValidateRetainedScroll()
        {
            var root = new VisualElement();
            var tree = new NativeViewTree();
            try
            {
                tree.Begin(root);
                var scroll = tree.Get(root, "scroll", () => new ScrollView());
                tree.TrackContainer(scroll, "content", scroll.contentContainer);
                var first = tree.Get(scroll.contentContainer, "copy", () => new Label("source text"));
                tree.End();
                tree.Begin(root);
                var secondScroll = tree.Get(root, "scroll", () => new ScrollView());
                tree.TrackContainer(secondScroll, "content", secondScroll.contentContainer);
                var second = tree.Get(secondScroll.contentContainer, "copy", () => new Label("source text"));
                tree.End();
                if (first != second || scroll != secondScroll || scroll.contentContainer.childCount != 1)
                    throw new Exception("Retained scroll content duplicated after a layout update.");
                tree.Begin(root);
                scroll = tree.Get(root, "scroll", () => new ScrollView());
                tree.TrackContainer(scroll, "content", scroll.contentContainer);
                tree.End();
                if (first.enabledSelf)
                    throw new Exception("Retired scroll content still accepts input.");
                Debug.Log("Retained scroll validation passed: stable identity, one child after rebuild, inactive exit.");
            }
            finally { NativeUi.Forget(root); }
        }
        private static void ValidateRetainedOrder()
        {
            var root = new VisualElement();
            var tree = new NativeViewTree();
            tree.Begin(root);
            tree.Get(root, "intro", () => new Label("Intro"));
            var action = tree.Get(root, "action", () => new Button());
            tree.End();
            tree.Begin(root);
            tree.Get(root, "intro", () => new Label());
            var inserted = tree.Get(root, "new-mode-note", () => new Label("Local play"));
            var retainedAction = tree.Get(root, "action", () => new Button());
            tree.End();
            if (action != retainedAction || root.IndexOf(inserted) >= root.IndexOf(action))
                throw new Exception("Retained form fields moved after the action buttons.");
            NativeUi.Forget(root);
            Debug.Log("Retained form validation passed: inserted content precedes the same action button.");
        }
    }
}
